// Some portions generated by Claude
package org.eclipse.rdf4j.query.parser.sparql;

import static org.assertj.core.api.Assertions.assertThatCode;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.List;

import org.eclipse.rdf4j.query.MalformedQueryException;
import org.eclipse.rdf4j.query.algebra.QueryRoot;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.parser.ParsedTupleQuery;
import org.junit.jupiter.api.Test;

/**
 * Each window specification marker ({@code winf:partitionBy}, {@code winf:orderBy}, {@code winf:rows} /
 * {@code winf:range}) may appear at most once per window function call; a repeated marker is a syntax error whose
 * message names the marker instead of being silently merged with the first occurrence.
 */
class WindowMarkerDuplicateParserTest {

	private static final String PREFIX = "PREFIX winf: <http://rdf4j.org/function/window#> PREFIX ex: <http://ex/> ";

	private static TupleExpr parse(String query) {
		TupleExpr expr = ((ParsedTupleQuery) new SPARQLParser().parseQuery(PREFIX + query, null)).getTupleExpr();
		return expr instanceof QueryRoot root ? root.getArg() : expr;
	}

	@Test
	void duplicatePartitionByIsRejected() {
		String query = "SELECT (winf:rank(winf:partitionBy(?d), winf:partitionBy(?s), winf:orderBy(?s)) AS ?a)"
				+ " WHERE { ?x ex:d ?d ; ex:s ?s }";
		assertThatThrownBy(() -> parse(query)).as(query)
				.isInstanceOf(MalformedQueryException.class)
				.hasMessageContaining("winf:partitionBy may appear only once in a window function call");
	}

	@Test
	void duplicateOrderByIsRejected() {
		String query = "SELECT (winf:rank(winf:orderBy(?d), winf:orderBy(?s)) AS ?a) WHERE { ?x ex:d ?d ; ex:s ?s }";
		assertThatThrownBy(() -> parse(query)).as(query)
				.isInstanceOf(MalformedQueryException.class)
				.hasMessageContaining("winf:orderBy may appear only once in a window function call");
	}

	@Test
	void duplicateFrameMarkersAreRejected() {
		for (String frames : List.of("winf:rows(-1, 0), winf:rows(0, 1)", "winf:range(-1, 0), winf:range(0, 1)",
				"winf:rows(-1, 0), winf:range(0, 1)", "winf:range(-1, 0), winf:rows(0, 1)")) {
			String query = "SELECT (winf:sum(?s, winf:orderBy(?s), " + frames + ") AS ?a) WHERE { ?x ex:s ?s }";
			assertThatThrownBy(() -> parse(query)).as(query)
					.isInstanceOf(MalformedQueryException.class)
					.hasMessageContaining("may appear only once in a window function call");
		}
	}

	@Test
	void duplicateMarkerIsRejectedRegardlessOfPosition() {
		// the repeated marker is not adjacent to the first and the function has its own argument in between
		String query = "SELECT (winf:sum(winf:orderBy(?d), ?s, winf:partitionBy(?d), winf:orderBy(?s)) AS ?a)"
				+ " WHERE { ?x ex:d ?d ; ex:s ?s }";
		assertThatThrownBy(() -> parse(query)).as(query)
				.isInstanceOf(MalformedQueryException.class)
				.hasMessageContaining("winf:orderBy may appear only once in a window function call");
	}

	@Test
	void singleMarkersWithSeveralKeysStayValid() {
		// several keys inside ONE marker is the supported way of partitioning / ordering by more than one expression
		assertThatCode(() -> parse("SELECT (winf:rank(winf:partitionBy(?d, ?s), winf:orderBy(?s, winf:desc(?d)),"
				+ " winf:rows(-1, 0)) AS ?a) WHERE { ?x ex:d ?d ; ex:s ?s }")).doesNotThrowAnyException();
		// and one marker of each kind per call, in any order, is fine
		assertThatCode(() -> parse("SELECT (winf:sum(?s, winf:rows(-1, 0), winf:orderBy(?s), winf:partitionBy(?d))"
				+ " AS ?a) WHERE { ?x ex:d ?d ; ex:s ?s }")).doesNotThrowAnyException();
	}
}
